<?php

declare(strict_types=1);

namespace App\Support;

use App\Models\User;

/**
 * Helper avatar: prioritizes uploaded photo, then Gravatar-style
 * identicon generated by UI Avatars (no user data leaked beyond name),
 * and falls back to an initials circle rendered by the <x-avatar> component.
 */
class Avatar
{
    public static function url(?User $user): ?string
    {
        if (! $user) {
            return null;
        }

        if ($user->avatar_path) {
            return \Storage::disk('public')->url($user->avatar_path);
        }

        // No external service: the <x-avatar> component renders initials
        // locally (privacy-friendly and works offline).
        return null;
    }
}
